/// Looks up a diagnostic by its numeric code.
pub fn lookup(code: u32) -> Option<&'static DiagnosticInfo> {
    ALL.binary_search_by_key(&code, |d| d.code)
        .ok()
        .map(|i| &ALL[i])
}
